namespace Ehr.Data.Patients;

// A diagnosis on a patient's chart, shaped on FHIR's Condition. PHI: row-level security is enabled and forced on it and
// every write is recorded by trigger (db/policies); reads go through the PHI reader in Ehr.Domain, which records them.
// Nothing at runtime writes it yet. Synthetic data only.
public class Condition
{
    // UUIDv7, generated by whoever creates the row.
    public Guid Id { get; set; }

    public Guid PatientId { get; set; }

    // The diagnosis as an ICD-10-CM code, when it has one.
    public string? Code { get; set; }

    // The diagnosis as clinicians read it, such as "Essential (primary) hypertension".
    public required string Display { get; set; }

    // One of ConditionClinicalStatus.
    public required string ClinicalStatus { get; set; }

    public DateOnly? OnsetDate { get; set; }
}

// FHIR's condition clinical status codes, the values Condition.ClinicalStatus may hold.
public static class ConditionClinicalStatus
{
    public const string Active = "active";

    public const string Recurrence = "recurrence";

    public const string Relapse = "relapse";

    public const string Inactive = "inactive";

    public const string Remission = "remission";

    public const string Resolved = "resolved";

    public static readonly string[] All = [Active, Recurrence, Relapse, Inactive, Remission, Resolved];

    // The ones that mean the patient has it now.
    public static readonly string[] Current = [Active, Recurrence, Relapse];
}
